package com.xjtu.iron.idempotent.api.repository;public final class IdempotencyAcquireResult{private final IdempotencyAcquireStatus status;private final IdempotencyRecord record;private final boolean takeover;private final Throwable error;private IdempotencyAcquireResult(IdempotencyAcquireStatus s,IdempotencyRecord r,boolean t,Throwable e){status=s;record=r;takeover=t;error=e;}public static IdempotencyAcquireResult of(IdempotencyAcquireStatus s,IdempotencyRecord r){return new IdempotencyAcquireResult(s,r,false,null);}public static IdempotencyAcquireResult acquired(IdempotencyRecord r,boolean t){return new IdempotencyAcquireResult(IdempotencyAcquireStatus.ACQUIRED,r,t,null);}public static IdempotencyAcquireResult providerError(Throwable e){return new IdempotencyAcquireResult(IdempotencyAcquireStatus.PROVIDER_ERROR,null,false,e);}public IdempotencyAcquireStatus getStatus(){return status;}public IdempotencyRecord getRecord(){return record;}public boolean isTakeover(){return takeover;}public Throwable getError(){return error;}}
